package org.codex.nfsugpreview;
import android.app.*;import android.os.*;import android.opengl.*;import java.nio.*;import java.nio.file.*;import java.io.*;import org.json.*;
public final class RoadEdgeGpuInstrumentation extends SceneGpuInstrumentation{
 int checks,writes;
 void verify(NativeRoadAsset asset,NativeRoadEdgePlan plan,NativeSceneSnapshot scene,int[] records,int width,int height,int top,int bottom)throws Exception{
  int[] id={0};GLES20.glGenTextures(1,id,0);int texture=id[0];GLES20.glBindTexture(GLES20.GL_TEXTURE_2D,texture);GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D,GLES20.GL_TEXTURE_MIN_FILTER,GLES20.GL_NEAREST);GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D,GLES20.GL_TEXTURE_MAG_FILTER,GLES20.GL_NEAREST);GLES20.glTexImage2D(GLES20.GL_TEXTURE_2D,0,GLES20.GL_RGBA,width,height,0,GLES20.GL_RGBA,GLES20.GL_UNSIGNED_BYTE,null);GLES20.glGenFramebuffers(1,id,0);int fbo=id[0];GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER,fbo);GLES20.glFramebufferTexture2D(GLES20.GL_FRAMEBUFFER,GLES20.GL_COLOR_ATTACHMENT0,GLES20.GL_TEXTURE_2D,texture,0);ok(GLES20.glCheckFramebufferStatus(GLES20.GL_FRAMEBUFFER)==GLES20.GL_FRAMEBUFFER_COMPLETE,"Edge FBO");GLES20.glDisable(GLES20.GL_SCISSOR_TEST);GLES20.glColorMask(true,true,true,true);GLES20.glClearColor(0,0,0,0);GLES20.glClear(GLES20.GL_COLOR_BUFFER_BIT);
  try(NativeRoadEdgeGpu gpu=new NativeRoadEdgeGpu()){writes+=gpu.draw(asset,plan,scene,width,height,top,bottom);}
  ByteBuffer pixels=ByteBuffer.allocateDirect(width*height*4);GLES20.glReadPixels(0,0,width,height,GLES20.GL_RGBA,GLES20.GL_UNSIGNED_BYTE,pixels);ok(GLES20.glGetError()==GLES20.GL_NO_ERROR,"Edge readback");int[] expected=new int[38400];java.util.Arrays.fill(expected,-1);for(int i=0;i<records.length;i+=3)if(records[i+1]>=top&&records[i+1]<bottom)expected[records[i+1]*240+records[i]]=records[i+2];ByteBuffer palette=NativeHistoricalPalette.rgba(scene),source=asset.texture();
  for(int y=0;y<160;y++)for(int x=0;x<240;x++){int xx=(int)Math.floor((x+.5)*width/240.),yy=height-1-(int)Math.floor((y+.5)*height/160.),at=(yy*width+xx)*4,offset=expected[y*240+x];if(offset<0){ok(pixels.get(at+3)==0,"Unexpected edge coverage");}else{int index=source.get(offset)&255;for(int c=0;c<4;c++)ok(pixels.get(at+c)==palette.get((y*256+index)*4+c),"Edge color "+x+","+y);}checks++;}
  GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER,0);GLES20.glDeleteFramebuffers(1,new int[]{fbo},0);GLES20.glDeleteTextures(1,new int[]{texture},0);
 }
 @Override public void onStart(){Bundle result=new Bundle();boolean live=false;try{File dir=new File(getTargetContext().getFilesDir(),"road-edge-fixtures");ByteBuffer ref=ByteBuffer.wrap(Files.readAllBytes(new File(dir,"edge-reference.bin").toPath())).order(ByteOrder.LITTLE_ENDIAN);int[] reciprocal=new int[32768];for(int i=0;i<32768;i++)reciprocal[i]=ref.getInt();int count=ref.getInt();NativeBackgroundScene frame=new NativeBackgroundScene(Files.readAllBytes(new File(dir,"race-background-whole.nrb").toPath()));NativeRoadAsset retained=null;NativeRoadEdgePlan retainedPlan=null;int[] retainedRecords=null;startGl();live=true;
  for(int i=0;i<count;i++){byte[] name=new byte[ref.getInt()];ref.get(name);NativeRoadAsset asset=new NativeRoadAsset(Files.readAllBytes(new File(dir,new String(name,"UTF-8")).toPath()));int[] records=new int[ref.getInt()*3];for(int j=0;j<records.length;j++)records[j]=ref.getInt();NativeRoadEdgePlan plan=new NativeRoadEdgePlan(asset,reciprocal,238);verify(asset,plan,frame.sky.scene,records,240,160,0,160);if(i<2)verify(asset,plan,frame.sky.scene,records,3840,2160,17,143);retained=asset;retainedPlan=plan;retainedRecords=records;}
  endGl();live=false;startGl();live=true;verify(retained,retainedPlan,frame.sky.scene,retainedRecords,240,160,0,160);JSONObject report=new JSONObject();report.put("result","PASS_ANDROID_ROAD_EDGE_GPU");report.put("assets",count);report.put("pixel_checks",checks);report.put("writes",writes);report.put("context_recreated",true);report.put("renderer",renderer);report.put("scene_order_integrated",false);try(FileOutputStream out=getTargetContext().openFileOutput("road-edge-gpu-report.json",0)){out.write(report.toString(2).getBytes("UTF-8"));}result.putString("stream",report.toString());finish(Activity.RESULT_OK,result);
 }catch(Throwable e){android.util.Log.e("NFSUGEdgeGPU","Failed",e);result.putString("stream","FAIL: "+e);finish(Activity.RESULT_CANCELED,result);}finally{if(live)endGl();}}
}
